refentry.refsect1:
&reftitle.description;
intcurl_multi_exec CurlMultiHandlemulti_handle intstill_running
Processa ogni handle nello stack. Questo metodo può essere chiamato indipendentemente dal fatto che un handle necessiti o meno di leggere o scrivere dati.

&reftitle.parameters;



  &curl.mh.description;

   still_running



     Un riferimento ad un flag per dire se le operazioni sono ancora in esecuzione.

&reftitle.returnvalues;
Un codice cURL definito nelle Costanti Predefinite di cURL.
Questa funzione restituisce solo errori riguardanti l'intero stack multiplo. Potrebbero essersi verificati problemi su singoli trasferimenti anche quando questa funzione restituisce CURLM_OK.

  &reftitle.examples;



    Esempio di curl_multi_exec


     Questo esempio creerà degli handle curl per un elenco di URL, li aggiungerà ad un handle
     multiplo, e poi li eseguirà in modo asincrono.



<?php

$urls = [
    "https://www.php.net/",
    "https://www.example.com/",
];

$mh = curl_multi_init();
$map = new WeakMap();

foreach ($urls as $url) {
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
    curl_multi_add_handle($mh, $ch);
    $map[$ch] = $url;
}

do {
    $status = curl_multi_exec($mh, $unfinishedHandles);
    if ($status !== CURLM_OK) {
        throw new \Exception(curl_multi_strerror(curl_multi_errno($mh)));
    }

    while (($info = curl_multi_info_read($mh)) !== false) {
        if ($info['msg'] === CURLMSG_DONE) {
            $handle = $info['handle'];
            curl_multi_remove_handle($mh, $handle);
            $url = $map[$handle];

            if ($info['result'] === CURLE_OK) {
                $statusCode = curl_getinfo($handle, CURLINFO_HTTP_CODE);

                echo "Richiesta a {$url} completata con lo stato HTTP {$statusCode}:", PHP_EOL;
                echo curl_multi_getcontent($handle);
                echo PHP_EOL, PHP_EOL;
            } else {
                echo "Richiesta a {$url} fallita con l'errore: ", PHP_EOL;
                echo curl_strerror($info['result']);
                echo PHP_EOL, PHP_EOL;
            }
        }
    }

    if ($unfinishedHandles) {
        if (($updatedHandles = curl_multi_select($mh)) === -1) {
            throw new \Exception(curl_multi_strerror(curl_multi_errno($mh)));
        }
    }
} while ($unfinishedHandles);

curl_multi_close($mh);

?>
